def build(report_path, screenshots, output):
    report = json.loads(report_path.read_text(encoding="utf-8"))
    statuses = Counter(entry["status"] for entry in report["equipment"])
    figures = []
    for name, title, caption in (
        ("home", "The original home", "Captured in the isolated staging client."),
        ("gear", "The expanded armory", "Real equipment capture from the staging test."),
        ("map", "Varlamore scenery", "Real map capture from the relocated staging area."),
    ):
        path = screenshots / f"{name}.png"
        if path.is_file():
            raw = path.read_bytes()
            if not raw.startswith(b"\x89PNG\r\n\x1a\n"):
                raise ValueError(f"Expected a PNG screenshot: {path}")
            width, height = struct.unpack(">II", raw[16:24])
            payload = base64.b64encode(raw).decode("ascii")
            figures.append(f'<figure><img src="data:image/png;base64,{payload}" alt="{escape(title)} in the Kronos staging client" width="{width}" height="{height}"><figcaption><strong>{escape(title)}.</strong> {escape(caption)}</figcaption></figure>')
    gallery = ""
    if figures:
        gallery = ('<section class="section" aria-labelledby="screens-title"><div class="section-head"><div><p class="eyebrow">From the staging client</p>'
                   '<h2 id="screens-title">A look inside the test world.</h2></div><p>Actual staging screenshots. These show the test build before release.</p></div><div class="gallery">'
                   + "".join(figures) + '</div></section>')
    values = {
        "ITEMS": f'{len(report["item_mapping"]):,}',
        "WEARABLES": f'{sum(value for status, value in statuses.items() if status.startswith("basic-equipment")):,}',
        "MODELS": f'{report["added_model_groups"]:,}',
        "REGIONS": str(len(report["map_regions"])),
        "REFRESHES": f'{len(report["visual_refreshes"]):,}',
        "SEQUENCES": f'{report["animations"]["added_sequences"]:,}',
        "LANDING": f'{report["map_landing"][0]}, {report["map_landing"][1]}',
        "COMMIT": escape(report["source_commit"], quote=True),
        "SHORTCOMMIT": escape(report["source_commit"][:7]),
        "BUILD": "Staged build " + escape(report_path.parent.name.rsplit("-", 1)[-1]),
        "GALLERY": gallery,
    }
    html = TEMPLATE
    for key, value in values.items():
        html = html.replace(f"@@{key}@@", value)
    if "@@" in html:
        raise ValueError("Unfilled feature-page template token")
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(html, encoding="utf-8")
    print(f"Created {output} ({output.stat().st_size:,} bytes; {len(figures)} real screenshots)")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--report", type=Path, default=Path("local-runtime/content242-stage-04/import-report.json"))
    parser.add_argument("--screenshots", type=Path, default=Path("local-runtime/content242-test-04/captures"))
    parser.add_argument("--output", type=Path, default=Path("content-release/Kronos-242-Features.html"))
    args = parser.parse_args()
    build(args.report, args.screenshots, args.output)
